const $=s=>document.querySelector(s);let reviewEditing=null,setupState;let state,previewID,page=0,total=0,editing=null;
function el(tag,text,cls){const x=document.createElement(tag);if(text!==undefined)x.textContent=text;if(cls)x.className=cls;return x}
function notice(text,error=false){$('#notice').textContent=text;$('#notice').classList.toggle('error',error);$('#notice').hidden=false}
async function api(path,data){const r=await fetch('/api/'+path,data===undefined?{}:{method:'POST',headers:{'Content-Type':'application/json','X-Qingyan-Token':state.token},body:JSON.stringify(data)});const v=await r.json();if(!r.ok)throw Error(v.error||'操作失败');return v}
function task(fn){return async function(...args){const b=args[0]?.currentTarget;if(b?.tagName==='BUTTON')b.disabled=true;try{await fn(...args)}catch(e){notice(e.message,true)}finally{if(b?.tagName==='BUTTON')b.disabled=false;if(b?.id==='prev')b.disabled=page===0;if(b?.id==='next')b.disabled=(page+1)*50>=total;if(b?.id==='phrase-move')b.disabled=!phraseSelection.size}}}
async function refresh(){await loadUpgradeReport();const draft=configPending?configurationValues():null;state=await api('state');$('#dirty').textContent='有待检查的配置';$('#apply').disabled=!state.ready;$('#installed').textContent=state.installed?'鼠须管已安装':'尚未安装鼠须管';$('#page-size').value=state.settings.page_size;$('#learning').checked=state.settings.learning;$('#show-pinyin').checked=state.settings.show_pinyin!==false;$('#abbreviation').checked=state.settings.abbreviation!==false;$('#auto-save-config').checked=!!state.settings.auto_save;fillHabits(state.settings);document.querySelectorAll('[data-fuzzy]').forEach(x=>x.checked=(state.fuzzy||[]).includes(x.dataset.fuzzy));$('#data-path').textContent='本地数据：'+state.data_path;$('#lib-count').textContent=state.libraries.length+' 个导入词库';const list=$('#lib-list');list.replaceChildren();for(const lib of state.libraries){const card=el('div',undefined,'card'),icon=el('div','词','icon'),body=el('div',undefined,'grow');body.append(el('strong',lib.name),el('p',lib.count.toLocaleString()+' 个词 · '+(lib.enabled?'已启用':'已停用')+(lib.review?' · '+lib.review+' 条特殊编码待修改拼音':'')));const toggle=el('input');toggle.type='checkbox';toggle.checked=lib.enabled;toggle.setAttribute('aria-label','启用 '+lib.name);toggle.onchange=task(async()=>{await api('library',{id:lib.id,enabled:toggle.checked});await refresh()});const remove=el('button','移除','text-button');remove.onclick=task(async()=>{if(!confirm('移除“'+lib.name+'”？原始文件不受影响，可重新导入。'))return;await api('library',{id:lib.id,delete:true});await refresh()});const exportLink=el('a','导出');exportLink.href='/api/library-export?id='+encodeURIComponent(lib.id);exportLink.download='';card.append(icon,body,toggle,exportLink);if(lib.manual){const edit=el('button','编辑');edit.onclick=task(()=>editLibrary(lib));card.append(edit)}card.append(remove);list.append(card)}await extraRefresh();await checkStatus();if(!$('#words').hidden)await loadWords();if(!$('#quick-pane').hidden)await loadQuick();if(draft)fillConfiguration(draft);renderSaveStatus()}
