let waitingJob=false;
function showJob(j){$('#deployment-progress').hidden=false;const labels={backup:'备份当前配置',compile:'编译词库',check:'检查全拼与简拼',restore:'恢复配置文件',load:'请求输入法加载',done:'处理完成',failed:'处理未完成'};$('#progress-title').textContent=labels[j.stage]||'准备中';$('#progress-steps').textContent=j.error||(j.kind==='recover'?'备份 → 恢复 → 加载':'备份 → 编译 → 输入检查 → 加载')+(j.running?' · 请稍候':'');$('#retry-deploy').hidden=j.stage!=='failed';$('#recover-config').hidden=j.running||!setupState?.can_recover;$('#apply').disabled=j.running;}
async function followJob(){if(waitingJob)return;waitingJob=true;try{let j;do{j=await api('job');if(j.stage!=='idle')showJob(j);if(j.running)await new Promise(r=>setTimeout(r,650))}while(j.running);await refresh();if(j.stage==='failed')throw Error(j.error);if(j.stage==='done')notice(j.result.message||(j.result.redeploy?'词库已编译，已请求加载，请切换到 KongIME 试打。':'词库已编译，请从输入法菜单重新部署后试打。'));return j;}finally{waitingJob=false}}
