var configTimer,configPending=false,configSerial=Promise.resolve(),configEditVersion=0;
function configurationValues(){return{appearance:appearanceValues(),fuzzy:[...document.querySelectorAll('[data-fuzzy]:checked')].map(x=>x.dataset.fuzzy),settings:{abbreviation:$('#abbreviation').checked,page_size:Number($('#page-size').value),learning:$('#learning').checked,show_pinyin:$('#show-pinyin').checked,auto_save:$('#auto-save-config').checked,language_hint:$('#language-hint').checked,pair_chinese:$('#pair-chinese').checked,pair_english:$('#pair-english').checked,ascii_punctuation:$('#ascii-punctuation').checked,direct_english:$('#direct-english').checked,recognize_addresses:$('#recognize-addresses').checked,shortcuts:Object.fromEntries([...document.querySelectorAll('[data-shortcut]')].map(x=>[x.dataset.shortcut,x.value]))}}}
