let inputChecklistKey='',inputChecklistDone=new Set();
function renderInputChecklist(){if(!state)return;const items=buildInputChecklist(configurationValues(),state.phrases),key=JSON.stringify(items);if(key!==inputChecklistKey){inputChecklistKey=key;inputChecklistDone.clear()}const box=$('#input-checklist');box.replaceChildren();for(const item of items){const row=el('div',undefined,'test-check-row'),label=el('label',undefined,'check'),check=el('input');check.type='checkbox';check.checked=inputChecklistDone.has(item.id);check.onchange=()=>{if(check.checked)inputChecklistDone.add(item.id);else inputChecklistDone.delete(item.id)};label.append(check,el('span',item.title+'：'+item.expected));const button=el('button','试打 '+item.code);button.type='button';button.onclick=()=>{$('#sandbox-hint').textContent='切换到 KongIME 中文状态，输入 '+item.code+'。'+item.expected;$('#sandbox-input').focus()};row.append(label,button);box.append(row)}}

async function loadUpgradeReport(){const r=await api('upgrade-check');const box=$('#upgrade-report');box.hidden=!r;if(!r)return;$('#upgrade-summary').textContent='KongIME '+r.version+' · '+r.time+' · '+(r.ok?'当前个人数据可读取':'发现需要处理的问题')+(r.changed_since?'；检查后有修改，请重新检查。':'');const details=$('#upgrade-details');details.replaceChildren();details.append(el('p',Object.entries(r.counts).map(([k,v])=>k+' '+v).join(' · ')));for(const error of r.errors)details.append(el('p',error));if(r.backup_error)details.append(el('p',r.backup_error));const messages={none:'没有可用的旧版快照，已检查当前数据结构；不能据此确认升级前后的内容一致。',same:'词库、短语和个性化设置与最近快照核对一致。',different:'与最近快照有差异，可能包含升级前的正常修改，不代表数据丢失。可在备份与恢复中预览后选择恢复。',unavailable:'旧版快照无法校验，当前数据与旧版是否一致尚不能确认。'};details.append(el('p',messages[r.comparison],'footnote'));for(const c of r.categories||[])if(c.added+c.removed+c.changed)details.append(el('p',c.label+'：新增 '+c.added+'、减少 '+c.removed+'、修改 '+c.changed,'footnote'));details.append(el('p','升级后请保存并应用配置。学习词频和各应用最近的中英文状态不在本项核对范围。','footnote'))}
